<script setup lang="ts">import { onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { getReceipt } from "../api"; const route = useRoute(); const receipt = ref<Awaited<ReturnType<typeof getReceipt>> | null>(null); const money = (value: number) => new Intl.NumberFormat("es-ES", { style: "currency", currency: "EUR" }).format(value / 100); function download() { window.open(`/api/payments/${route.params.id}/pdf`, "_blank"); } onMounted(async () => { receipt.value = await getReceipt(String(route.params.id)); });</script><template><section v-if="receipt" class="customer-detail"><p class="breadcrumb"><RouterLink :to="{ name: 'payments.list' }">TPV</RouterLink> / Recibo</p><header><div><p class="eyebrow">Recibo</p><h1>{{ money(receipt.payment.amountCents) }}</h1><span class="status-pill">{{ receipt.payment.status }}</span></div><button @click="download">Descargar PDF</button></header><section class="detail-tab"><dl><dt>Cliente</dt><dd>{{ receipt.customer.displayName }}</dd><dt>Reparacion</dt><dd>{{ receipt.repair.brand }} {{ receipt.repair.model }}</dd><dt>Metodo</dt><dd>{{ receipt.payment.method }}</dd><dt>Referencia</dt><dd>{{ receipt.payment.reference || "Sin referencia" }}</dd></dl></section></section><p v-else class="empty">Cargando recibo...</p></template>